bash -lc 'set -e; python - <<"PY"
import io,sys
p="/src/mruby/mrbgems/mruby-sprintf/src/sprintf.c"
with open(p, "r", encoding="utf-8") as f:
    data = f.read()
old = '''        {
          size_t size;
          size = strlen(s);
          /* PARANOID: assert(size <= MRB_INT_MAX) */
          len = (mrb_int)size;
        }'''
new = '''        {
          size_t size;
          size = strlen(s);
          /* Avoid negative length on conversion to mrb_int by clamping to MRB_INT_MAX */
          if (size > (size_t)MRB_INT_MAX) {
            len = MRB_INT_MAX;
          } else {
            len = (mrb_int)size;
          }
        }'''
if old in data:
    data = data.replace(old, new)
    with open(p, "w", encoding="utf-8") as f:
        f.write(data)
    print("Patched size->len conversion block in sprintf.c")
else:
    print("Patch target not found; no changes made")
    sys.exit(1)
PY'

bash -lc 'set -e; python - << "PY"
p = "/src/mruby/mrbgems/mruby-sprintf/src/sprintf.c"
with open(p, "r", encoding="utf-8") as f:
  data = f.read()
anchor = "/* PARANOID: assert(size <= MRB_INT_MAX) */"
pos = data.find(anchor)
if pos < 0:
  print("anchor not found", file=sys.stderr)
  raise SystemExit(1)
len_pat = "len = (mrb_int)size;"
pos_len = data.find(len_pat, pos)
if pos_len < 0:
  print("len line not found", file=sys.stderr)
  raise SystemExit(1)
line_end = data.find("
", pos_len)
if line_end < 0:
  line_end = len(data)
replacement = "
  /* Avoid negative length on conversion to mrb_int by clamping to MRB_INT_MAX */
  if (size > (size_t)MRB_INT_MAX) {
    len = MRB_INT_MAX;
  } else {
    len = (mrb_int)size;
  }"
new_data = data[:pos] + replacement + data[line_end+1:]
with open(p, "w", encoding="utf-8") as f:
  f.write(new_data)
print("Patched sprintf.c")
PY'

